/// <summary>
/// MPJ_34596_TransferOrderFinalisation The <c>MetTransferOrderAutoShipController</c> class is a controller class for the <c>MetTransferOrderAutoShipService</c> service class.
/// </summary>
[SysOperationJournaledParameters(true)]
public final class MetTransferOrderAutoShipController extends SysOperationServiceController implements BatchRetryable,  SysErrorMessageHelpScopeIBatchProvider
{
}

