/// <summary>
/// Class description
/// </summary>
/// <returns>ClassDescription</returns>
private static ClassDescription description()
{
    return "@MET:AutoShipmentCreation";
}

    /// <summary>
    /// class instanitation
    /// </summary>
    /// <param name = "_className">className</param>
    /// <param name = "_methodName">methodName</param>
    /// <param name = "_executionMode">executionMode</param>
    protected void new(IdentifierName _className = '', IdentifierName _methodName='', SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
    {
        IdentifierName	parmClassName	= _className != '' ? _className : classStr(MetTransferOrderAutoShipService);
        IdentifierName	parmMethodName	= _methodName != '' ? _methodName : methodStr(MetTransferOrderAutoShipService, autoShipTransferOrders);

        super(parmClassName, parmMethodName, _executionMode);

        this.parmDialogCaption(MetTransferOrderAutoShipController::description());
    }

    /// <summary>
    /// SysOperationController construct
    /// </summary>
    /// <param name = "_args">args</param>
    /// <returns>SysOperationController</returns>
    [Hookable(false)]
    public static SysOperationController construct(Args _args)
    {
        SysOperationController controller = new MetTransferOrderAutoShipController(
			classstr(MetTransferOrderAutoShipService),
            methodstr(MetTransferOrderAutoShipService, autoShipTransferOrders),
			SysOperationExecutionMode::Synchronous);

        controller.parmArgs(_args);
        controller.parmDialogCaption(MetTransferOrderAutoShipController::description());

        return controller;
    }

/// <summary>
/// Main function
/// </summary>
/// <param name = "_args">args</param>
[Hookable(false)]
public static void main(Args _args)
{
    MetTransferOrderAutoShipController controller = MetTransferOrderAutoShipController::construct(_args);
    controller.startOperation();
}

/// <summary>
/// true in case run in session
/// </summary>
/// <returns>boolean</returns>
protected boolean canRunInNewSession()
{
    return true;
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable() 
{
    return true;
}

/// <summary>
/// Gets the form name used for the error context using a <c>SysErrorMessageHelpScope</c> class.
/// </summary>
/// <returns>The form name used for the error context.</returns>
[Hookable(false)]
public FormName errorMessageHelpScopeFormName()
{
    return strFmt('%1_%2', formStr(Dialog), classStr(MetTransferOrderAutoShipController));
}

/// <summary>
/// Gets the action name used for the error context using a <c>SysErrorMessageHelpScope</c> class.
/// </summary>
/// <returns>The action name used for the error context.</returns>
[Hookable(false)]
public str errorMessageHelpScopeActionName()
{
    return menuItemActionStr(MetTransferOrderAutoShip);
}
